#!/usr/bin/env python3
from __future__ import annotations
from pathlib import Path
import json
import pandas as pd
ROOT=Path('/home/ubuntu/CHAOS');OUT=ROOT/'experiments/macro_plus_eia_energy/transition_evidence_v1';OUT.mkdir(parents=True,exist_ok=True)
def edge(tid,src,tgt,lag,split,metric,null,p,holdout,refs,status,fails):
 return {'transition_id':tid,'source_state':src,'target_state':tgt,'lag':{'value':lag,'unit':'years','direction':'forward'},'split':split,'metric':metric,'null_method':null,'p_value':p,'entity_holdout':holdout,'source_refs':refs,'edge_status':status,'causal_claim':False,'failure_cases':fails}
def main():
 a=pd.read_csv(ROOT/'experiments/macro_plus_eia_energy/un_ama_replication_v1/UN_AMA_REPLICATION_METRICS.csv');cn=pd.read_csv(ROOT/'experiments/macro_plus_eia_energy/ama_ucdp_cross_domain_v1/AMA_UCDP_CROSS_DOMAIN_NULL_SUMMARY.csv');rows=[]
 ama_v=a[(a.split=='validation')&(a.model=='high_growth_rule')].iloc[0]; ama_c=a[(a.split=='confirmation')&(a.model=='high_growth_rule')].iloc[0]
 rows += [edge('AMA_HG_TO_MATERIAL_DROP_V1','AMA_HIGH_GROWTH_STATE_V1','AMA_MATERIAL_DROP_2PP_T_PLUS_3_V1',3,'validation',{'balanced_accuracy':float(ama_v.balanced_accuracy),'f1':float(ama_v.f1)},'within-country label permutation; 2000 reps',0.0005,False,['UN_AMA_2026','UN_AMA_REPLICATION_NULL_SUMMARY.csv'],'supported_predictive',['not causal','confirmation remains lower than validation']),edge('AMA_HG_TO_MATERIAL_DROP_V1','AMA_HIGH_GROWTH_STATE_V1','AMA_MATERIAL_DROP_2PP_T_PLUS_3_V1',3,'confirmation',{'balanced_accuracy':float(ama_c.balanced_accuracy),'f1':float(ama_c.f1)},'within-country label permutation; 2000 reps',0.0005,False,['UN_AMA_2026','UN_AMA_REPLICATION_NULL_SUMMARY.csv'],'supported_predictive',['not causal'])]
 for _,r in cn.iterrows():
  tgt='UCDP_STATE_CONFLICT_T_PLUS_3_V1' if r.outcome=='future_state_conflict' else 'UCDP_HIGH_FATALITY_25_T_PLUS_3_V1';status='rejected' if float(r.p_ba)>0.2 else 'unresolved'; rows.append(edge('AMA_HG_TO_'+tgt,'AMA_HIGH_GROWTH_STATE_V1',tgt,3,r.split,{'balanced_accuracy':float(r.observed_ba),'f1':float(r.observed_f1)},'within-country label permutation; 2000 reps',float(r.p_ba),False,['UN_AMA_2026','UCDP_CY_26_1','AMA_UCDP_CROSS_DOMAIN_NULL_SUMMARY.csv'],status,['cross-domain edge did not pass current null gate']))
