 df=pd.DataFrame(rows);df.to_json(OUT/'TRANSITION_EVIDENCE_V1.jsonl',orient='records',lines=True,force_ascii=False);df.to_csv(OUT/'TRANSITION_EVIDENCE_V1.csv',index=False);summary={'records':len(df),'supported_predictive':int((df.edge_status=='supported_predictive').sum()),'rejected':int((df.edge_status=='rejected').sum()),'unresolved':int((df.edge_status=='unresolved').sum()),'causal_claims':0,'native_lag_unit':'years','sources':['UN AMA 2026','UCDP Country-Year 26.1'],'raw_modified':False};(OUT/'TRANSITION_EVIDENCE_SUMMARY.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n');print(json.dumps(summary,ensure_ascii=False,indent=2));print(df.to_string(index=False))
